; HeroQuest MSX2 - intro
; DiHalt Studio
;
; The story told by Mentor, shown once after the studio logo: pictures with
; small animations and text screens, with the menu tune (on the OPL4 if
; there is one, on the PSG otherwise). ESC, SPACE or the right mouse button skips
; it. The program is copied to 8000h and called by rt_boot before the game
; is copied there (it goes back with a jump to rt_boot_game); it uses the loaders of the runtime in page 0, whose
; labels come from build/rt_all.inc. The pictures, texts, animations and
; the script are data generated by tools/build_intro.py (build/intro.inc)
; from assets/intro/ and src/intro_script.py.
;
; VRAM: pictures in page 0, text screens in pages 1 and 2, the sheet with
; the font and the animation frames in page 3.

        include "../build/rt_all.inc"

IN_STACK        equ 0xBFF0

        org INTRO_BASE
intro:
        di
        ld sp,IN_STACK
        ld a,0xC3               ; the interrupt entry of the runtime ends in
        ld (GAME_IRQ_JP),a      ; a jump to this address, where the game puts
        ld hl,in_irq            ; its own handler later
        ld (GAME_IRQ_JP+1),hl
        xor a
        ld (in_skip),a
        ld (in_music),a
        ld (in_time_skip),a
        ld a,0x2A               ; R#8: sprites off (the pointer)
        out (VDP_CTRL),a
        ld a,0x88
        out (VDP_CTRL),a
        call in_opening
        ei
        call in_select_language
        di
        call in_apply_language
        xor a
        ld (in_skip),a
        ld (in_time_skip),a
        ei
in_start_script:
        ld hl,in_script
in_next:
        ld a,(in_skip)
        or a
        jr nz,in_end
        ld a,(hl)
        inc hl
        or a
        jr z,in_end
        add a,a
        ld e,a
        ld d,0
        push hl
        ld hl,in_commands-2
        add hl,de
        ld e,(hl)
        inc hl
        ld d,(hl)
        pop hl
        ld bc,in_next
        push bc
        push de
        ret                     ; command: HL -> its parameters, returns HL after them

in_end:
        di
        ld a,5                  ; stop the music
        call RT2_SNDCMD
        xor a                   ; and let the tunes loop again
        ld (rt_opl_once),a
        ld h,a
        ld l,a
        call in_psg_ends
        ld a,0x22               ; display off
        out (VDP_CTRL),a
        ld a,0x81
        out (VDP_CTRL),a
        xor a                   ; show page 0 again
        call in_show_a
        ld a,0x28               ; sprites on
        out (VDP_CTRL),a
        ld a,0x88
        out (VDP_CTRL),a
        jp rt_boot_game

; The choice is made once per boot, before either language starts its story.
; Rendering can enable interrupts; the skip latch is cleared after all input
; is released so SPACE used here never skips the narrative.
in_select_language:
        xor a
        ld (rt_language),a      ; keep the existing Spanish game as default
        ld hl,in_select_clear
        call in_cls
        ld hl,in_select_font
        call in_picture
        ld hl,in_select_palette
        call in_palette
        ; Prepare both choices while the opening has the display off.
        ; Selection then changes only the visible VRAM page at vblank.
        ld hl,in_select_background
        call in_picture
        xor a
        ld (in_cmd+7),a
        ld hl,in_select_text_es
        call in_draw_glyphs
        ld hl,in_select_clear_en
        call in_cls
        ld hl,in_select_background_en
        call in_picture
        ld a,1
        ld (in_cmd+7),a
        ld hl,in_select_text_en
        call in_draw_glyphs
        call in_vdp_idle
        call in_select_draw
        ld hl,in_select_on
        call in_screen
in_select_release:
        halt
        call in_select_input
        or a
        jr nz,in_select_release
in_select_poll:
        halt
        call in_select_input
        bit 4,a
        jr nz,in_select_confirm
        bit 0,a
        jr nz,in_select_english
        bit 1,a
        jr z,in_select_poll
        xor a
        jr in_select_change
in_select_english:
        ld a,1
in_select_change:
        ld (rt_language),a
        call in_select_draw
        jr in_select_release
in_select_confirm:
        halt
        call in_select_input
        or a
        jr nz,in_select_confirm
        ret

in_select_draw:
        halt                    ; swap complete pages during vertical blank
        ld a,(rt_language)
        jp in_show_a

; Normalized menu input: bit 0 up, 1 down, 4 confirm. Read the matrix
; directly because the Spectrum input variables are not initialized yet.
in_select_input:
        di                      ; protect both keyboard matrix and PSG register selection
        ld a,8
        call rt_keyrow
        cpl
        ld c,a
        and 0x20
        rlca
        rlca
        rlca
        ld b,a                  ; UP -> bit 0
        ld a,c
        and 0x40
        rlca
        rlca
        rlca
        or b
        ld b,a                  ; DOWN -> bit 1
        ld a,c
        and 1
        rlca
        rlca
        rlca
        rlca
        or b
        ld b,a                  ; SPACE -> bit 4
        ld a,7
        call rt_keyrow
        cpl
        and 0x80                ; RETURN -> bit 4
        rrca
        rrca
        rrca
        or b
        ld b,a
        ld a,(rt_mouse_port)
        dec a
        jr z,in_select_mouse   ; mouse motion is not a joystick direction
        ld a,14
        out (PSG_ADDR),a
        in a,(PSG_READ)
        cpl
        and 0x13                ; joystick up, down, trigger
        or b
        jr in_select_input_done
in_select_mouse:
        ld a,(rt_mouse_btn)
        or a
        ld a,b
        jr z,in_select_input_done
        or 0x10
in_select_input_done:
        ei
        ret

in_select_clear:      db 0
in_select_clear_en:   db 1
in_select_font:       db 2,3
in_select_palette:    db 1
in_select_background: db 1,0
in_select_background_en: db 1,1
in_select_on:         db 1

; in_opening: the opening picture, 512 x 424 in 16 colours: SCREEN 7 with
; interlace, the even lines in page 0 and the odd lines in page 1, which the
; VDP shows in alternate fields. It stays until SPACE (or a fire button) is
; pressed. Runs with interrupts disabled: the interrupt entry of the runtime
; writes the pointer's sprite attributes, which are inside page 0 of this
; mode (rt_boot writes the sprite tables again after the intro).
in_opening:
        ld a,0x22               ; display off
        ld e,0x81
        call in_vdp_reg
        ld a,0x0A               ; R#0: SCREEN 7 (G6)
        ld e,0x80
        call in_vdp_reg
        ld hl,in_opening_palette
        call rt_set_palette
        xor a                   ; border: colour 0, black
        ld e,0x87
        call in_vdp_reg
        ld hl,in_cmd_fill7      ; both pages black
        call rt_vdp_cmd
        call in_vdp_idle_di
        ld hl,in_opening0
        call in_opening_field
        ld hl,in_opening1
        call in_opening_field
        ld a,(SYS_RG9SAV)       ; R#9 as the BIOS left it, plus interlace and
        or 0x0C                 ; alternate pages
        ld e,0x89
        call in_vdp_reg
        ld a,0x3F               ; R#2: page 1 (with page 0 in the even fields)
        ld e,0x82
        call in_vdp_reg
        ld a,0x62               ; display on
        ld e,0x81
        call in_vdp_reg
in_op_release:
        call in_fire
        jr nz,in_op_release
in_op_press:
        call in_fire
        jr z,in_op_press
in_op_release2:                 ; the key that left the opening must not skip the intro
        call in_fire
        jr nz,in_op_release2
        ld a,0x22               ; display off, back to SCREEN 5
        ld e,0x81
        call in_vdp_reg
        ld a,(SYS_RG9SAV)
        ld e,0x89
        call in_vdp_reg
        ld a,0x06
        ld e,0x80
        call in_vdp_reg
        ld a,0x1F
        ld e,0x82
        jp in_vdp_reg

; in_opening_field: load the blob at HL (a copy is made: the loader wants
; it in RAM that stays in place, like the pictures).
in_opening_field:
        ld de,in_blob
        ld bc,4+5*8
        ldir
        ld hl,in_blob
        jp rt_load_blob

; in_fire: NZ if SPACE, a joystick trigger or the left mouse button is down.
; Reads the hardware (no interrupts needed). Clobbers AF, BC.
in_fire:
        ld a,8                  ; keyboard row 8, bit 0: SPACE
        call rt_keyrow
        cpl
        and 1
        ret nz
        ld a,14                 ; PSG register 14: joystick port, bits 4-5 triggers
        out (PSG_ADDR),a
        in a,(PSG_READ)
        cpl
        and 0x10
        ret

; in_vdp_reg: VDP register write: value A, then E = 80h + register.
in_vdp_reg:
        out (VDP_CTRL),a
        ld a,e
        out (VDP_CTRL),a
        ret

; in_vdp_idle_di: wait for the VDP command to end, interrupts disabled.
in_vdp_idle_di:
        ld a,2
        out (VDP_CTRL),a
        ld a,0x8F
        out (VDP_CTRL),a
        in a,(VDP_CTRL)
        ld b,a
        xor a
        out (VDP_CTRL),a
        ld a,0x8F
        out (VDP_CTRL),a
        bit 0,b
        jr nz,in_vdp_idle_di
        ret

in_cmd_fill7:                   ; SCREEN 7: 512 x 512 from the top of page 0, colour 0
        dw 0,0, 0,0, 512,512
        db 0,0,VCMD_HMMV

SYS_RG9SAV      equ 0xFFE8      ; BIOS copy of VDP register 9 (page 3 is untouched so far)

; interrupt: music, and the two ways to skip the intro
in_irq:
        push af
        push bc
        push de
        push hl
        push ix
        push iy
        exx
        ex af,af'
        push af
        push bc
        push de
        push hl
        ; Keep scripted waits and animation delays on the same 50 Hz clock
        ; as the music. A 60 Hz machine contributes five ticks per six IRQs.
        ld a,(rt_60hz)
        or a
        jr z,in_irq_music
        ld hl,in_time_skip
        inc (hl)
        ld a,(hl)
        cp 6
        jr c,in_irq_music
        ld (hl),0
in_irq_music:
        ld a,(in_music)
        or a
        call nz,rt_music_tick
        ld a,7                  ; keyboard row 7, bit 2: ESC
        call rt_keyrow
        cpl
        and 4
        ld b,a
        ld a,8                  ; keyboard row 8, bit 0: SPACE
        call rt_keyrow
        cpl
        and 1
        or b
        ld b,a
        ld a,(rt_mouse_btn2)
        or b
        jr z,in_irq_done
        ld (in_skip),a
in_irq_done:
        pop hl
        pop de
        pop bc
        pop af
        ex af,af'
        exx
        pop iy
        pop ix
        pop hl
        pop de
        pop bc
        pop af
        ei
        ret

in_commands:
        dw in_cls, in_picture, in_palette, in_show, in_screen, in_wait, in_text, in_anim, in_start_music

; cls page
in_cls:
        ld a,(hl)
        inc hl
        push hl
        ld hl,0
        ld (in_cmd+4),hl        ; DX
        ld (in_cmd+8),hl        ; NX = 256
        ld (in_cmd+12),hl       ; colour 0
        ld h,a
        ld (in_cmd+6),hl        ; DY = page * 256
        ld hl,212               ; NY: only the visible lines (the hidden
        ld (in_cmd+10),hl       ; lines of page 0 hold the sprite tables)
        ld a,1
        ld (in_cmd+9),a
        ld a,VCMD_HMMV
        jp in_run

; picture number, page: load it from ROM
in_picture:
        call in_vdp_idle        ; a clear of the page may still be running: it
        ld e,(hl)               ; would wipe the first lines of the picture
        inc hl
        ld a,(hl)
        inc hl
        push hl
        push af
        ld a,e
        or a
        jr nz,in_picture_selected
        ld a,(rt_language)
        or a
        jr z,in_picture_selected
        ld e,IN_TITLE_EN        ; English title credits, same palette and artwork
in_picture_selected:
        ld d,0
        ld hl,in_pictures
        add hl,de
        add hl,de
        ld e,(hl)
        inc hl
        ld d,(hl)
        ex de,hl                ; HL -> blob: VRAM address, pieces
        ld de,in_blob
        ld bc,4+5*8
        ldir
        pop af
        add a,a                 ; page -> bits 16-15 of the VRAM address
        ld hl,in_blob
        add a,(hl)
        ld (hl),a
        call rt_load_blob
        pop hl
        ret

; in_vdp_idle: wait until the VDP has finished its command.
; Keeps every register but AF.
in_vdp_idle:
        push bc
in_vi_wait:
        di
        ld a,2
        out (VDP_CTRL),a
        ld a,0x8F               ; R#15 = 2: status register 2
        out (VDP_CTRL),a
        in a,(VDP_CTRL)
        ld b,a
        xor a
        out (VDP_CTRL),a
        ld a,0x8F               ; R#15 = 0 again for the interrupt entry
        out (VDP_CTRL),a
        ei
        bit 0,b                 ; CE: command executing
        jr nz,in_vi_wait
        pop bc
        ret

; palette of picture number
in_palette:
        ld a,(hl)
        inc hl
        push hl
        ld l,a
        ld h,0
        add hl,hl
        add hl,hl
        add hl,hl
        add hl,hl
        add hl,hl               ; 32 bytes each
        ld de,in_palettes
        add hl,de
        di
        call rt_set_palette
        ei
        pop hl
        ret

; show page
in_show:
        ld a,(hl)
        inc hl
in_show_a:
        rrca
        rrca
        rrca
        or 0x1F                 ; R#2: page in bits 6-5
        push af
        call rt_iff
        jp po,in_show_off
        di
        pop af
        out (VDP_CTRL),a
        ld a,0x82
        out (VDP_CTRL),a
        ei
        ret
in_show_off:
        pop af
        out (VDP_CTRL),a
        ld a,0x82
        out (VDP_CTRL),a
        ret

; screen 0/1: display off or on
in_screen:
        ld a,(hl)
        inc hl
        or a
        ld a,0x22
        jr z,in_screen_set
        ld a,0x62
in_screen_set:
        di
        out (VDP_CTRL),a
        ld a,0x81
        out (VDP_CTRL),a
        ei
        ret

; wait frames
in_wait:
        ld b,(hl)
        inc hl
; in_pause: wait B ticks at 50 Hz, or less if the intro is skipped.
; On a 50 Hz machine this is the original one-HALT-per-tick behaviour.
in_pause:
        ld a,(in_skip)
        or a
        ret nz
        halt
        ld a,(rt_60hz)
        or a
        jr z,in_pause_tick
        ld a,(in_time_skip)
        or a
        jr z,in_pause          ; sixth IRQ: music also skips this frame
in_pause_tick:
        djnz in_pause
        ret

; text number, page: copy its glyphs from the font in page 3
in_text:
        ld e,(hl)
        inc hl
        ld a,(hl)
        inc hl
        push hl
        ld (in_cmd+7),a         ; DY high: page
        ld d,0
        ld hl,in_texts_es
        ld a,(rt_language)
        or a
        jr z,in_text_language
        ld hl,in_texts_en
in_text_language:
        add hl,de
        add hl,de
        ld e,(hl)
        inc hl
        ld d,(hl)
        ex de,hl                ; HL -> x, y, glyph ... 255
        call in_draw_glyphs
        pop hl
        ret

; HL -> glyph triples terminated by 255; destination page in in_cmd+7.
in_draw_glyphs:
        ld a,8
        ld (in_cmd+8),a
        ld (in_cmd+10),a
        xor a
        ld (in_cmd+1),a
        ld (in_cmd+5),a
        ld (in_cmd+9),a
        ld (in_cmd+11),a
        ld (in_cmd+13),a
        ld a,3
        ld (in_cmd+3),a         ; SY high: page 3
        ld a,VCMD_LMMM_TIMP
        ld (in_cmd+14),a
in_text_glyph:
        ld a,(hl)
        cp 255
        jr z,in_text_done
        ld (in_cmd+4),a         ; DX
        inc hl
        ld a,(hl)
        ld (in_cmd+6),a         ; DY
        inc hl
        ld a,(hl)
        inc hl
        ld c,0                  ; glyphs 0-31 on line 0, the rest on line 9
        cp 32
        jr c,in_text_row
        sub 32
        ld c,9
in_text_row:
        add a,a
        add a,a
        add a,a
        ld (in_cmd),a           ; SX
        ld a,c
        ld (in_cmd+2),a         ; SY
        push hl
        ld hl,in_cmd
        call rt_vdp_cmd
        pop hl
        jr in_text_glyph
in_text_done:
        ret

; anim scene: copy its frames from page 3 over the picture in page 0, in
; turn, a number of passes
in_anim:
        ld e,(hl)
        inc hl
        push hl
        ld d,0
        ld hl,in_anims
        add hl,de
        add hl,de
        ld e,(hl)
        inc hl
        ld d,(hl)
        push de
        pop ix
        xor a
        ld (in_cmd+1),a
        ld (in_cmd+5),a
        ld (in_cmd+7),a         ; DY high: page 0
        ld (in_cmd+9),a
        ld (in_cmd+11),a
        ld (in_cmd+13),a
        ld a,3
        ld (in_cmd+3),a         ; SY high: page 3
        ld c,(ix+1)             ; passes
in_anim_pass:
        push ix
        pop hl
        inc hl
        inc hl
        ld d,(hl)               ; frames
        inc hl
in_anim_frame:
        ld b,(ix+0)             ; frames of the screen between two copies
        call in_pause
        ld a,(in_skip)
        or a
        jr nz,in_anim_done
        push de
        ld de,in_cmd
        ld b,3                  ; SX, SY, DX, DY, NX, NY: the low bytes
in_anim_field:
        ld a,(hl)
        ld (de),a
        inc hl
        inc de
        inc de
        ld a,(hl)
        ld (de),a
        inc hl
        inc de
        inc de
        djnz in_anim_field
        pop de
        ld a,0xD0               ; HMMM
        push hl
        push bc
        push de
        ld (in_cmd+14),a
        ld hl,in_cmd
        call rt_vdp_cmd
        pop de
        pop bc
        pop hl
        dec d
        jr nz,in_anim_frame
        dec c
        jr nz,in_anim_pass
in_anim_done:
        pop hl
        ret

; music: start the menu tune. In the intro it is played once: the OPL4
; stream stops at its end (rt_opl_once), and the three order lists of the
; PSG tune get the end mark of the driver (FFFFh) in place of the restart
; mark (0000h) until the intro ends.
in_start_music:
        push hl
        di
        ld a,1
        ld (rt_opl_once),a
        ld hl,0xFFFF
        call in_psg_ends
        ld a,3
        call RT2_SNDCMD
        ld d,2
        ld a,2
        call RT2_SNDCMD
        ld a,1
        ld (in_music),a
        ei
        pop hl
        ret

; in_psg_ends: write HL at the end of the three order lists of the PSG menu
; tune (addresses from the build, in the driver copied to page 0).
in_psg_ends:
        ld (PSG_TUNE2_END_A),hl
        ld (PSG_TUNE2_END_B),hl
        ld (PSG_TUNE2_END_C),hl
        ret

; in_run: run the VDP command in in_cmd with command code A; ends a script
; command whose HL is on the stack
in_run:
        ld (in_cmd+14),a
        ld hl,in_cmd
        call rt_vdp_cmd
        pop hl
        ret

in_skip:        db 0
in_music:       db 0
in_time_skip:   db 0            ; 60 Hz frame phase, 0 is the skipped sixth IRQ
in_cmd:         ds 15,0
in_blob:        ds 4+5*8,0

        include "../build/language.inc"
        include "../build/intro.inc"

        assert $ <= IN_STACK-0x100
